        let engine = PricingEngine::with_defaults();
        let price = engine.calculate_price(ComputeBackend::OnnxRuntime, 1);
        assert_eq!(price, 15_000_000_000); // 10_000_000_000 * 1.5 * 1
    }

    #[test]
    fn test_pricing_wasm_cheaper() {
        let engine = PricingEngine::with_defaults();
